    e.g.: [a,b,c,d] -> a, b, c and d
    """
def format_list(_list: Any) -> object {
    if (len(_list) == 0) {
        return "no one";
    } elif (len(_list) == 1) {
        return _list[0];
    } else {
        s = "";
        for e in _list[:(len(_list) - 2)] {
            s = s + str(e) + ", ";
        }
        s = s + str(_list[(len(_list) - 2)]) + " and " + str(_list[(len(_list) - 1)]);
        return s;
    }
}

