    """
def show_dictionary(name: Any, d: Any) -> object {
    text = [("[%s]" % name)];
    for key in d {
        text.append(
            ("\t%s = %s" % (key, d[key] if (d[key] is not None) else '<Not set>'))
        );
    }
    return '\n'.join(text);
}

