"""
    Color a string for terminal output
    @params
        str - Required : the string to color
        color - Optional : the color to use. Default value: red. Available options: red, yellow, blue
    """
def colored(str: Any, color: Any = "red") -> object {
    colors = {
        "red": "\033[91m",
        "yellow": "\33[33m",
        "blue": "\33[34m",
        "green": "\33[32m"
    };
    end = "\033[0m";
    return f"{colors[color]}{str}{end}";
}

"""
    Generates the first n Fibonacci numbers.
    Adopted from: https://docs.python.org/3/tutorial/modules.html
    """
def fibonacci(n: Any) -> object {
    result = [];
    (a, b) = (0, 1);
    while (len(result) < n) {
        result.append(b);
        (a, b) = (b, (a + b));
    }
    return result;
}
